import{z as o,x as A,o as s,c as p,q as r,j as E,D as e,d as l,s as B,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"PCIe 层次与 lane","description":"","frontmatter":{"title":"PCIe 层次与 lane","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pcie-lanes.md","filePath":"cs/pcie-lanes.md","lastUpdated":1791063341000}'),C={name:"cs/pcie-lanes.md"};function d(P,a,D,I,c,m){const t=A("Mermaid");return s(),p("div",null,[a[2]||(a[2]=r('<h1 id="pcie-层次与-lane" tabindex="-1">PCIe 层次与 lane <a class="header-anchor" href="#pcie-层次与-lane" aria-label="Permalink to &quot;PCIe 层次与 lane&quot;">​</a></h1><div class="epigraph"><p>PCIe 不是共享并行总线：点对点串行 lane 组成链路，分层为物理、数据链路与事务，设备各占自己的宽度。</p><footer>—— 据 PCI-SIG PCI Express Base Specification；Hennessy and Patterson, CA:AQA；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/hdd-geometry">上一课</a>把块设备停在内部几何。组成课的<a href="/cs/bus-mmio">总线与 MMIO</a> 是共享地址数据总线教学模型。缺口是当代互连 <strong>PCIe</strong>：lane、链路宽度 ×N、分层，让 SSD、GPU、网卡接到 CPU 根复合体。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PCI 并行总线仲裁、反射、频率上不去。PCIe：每 lane 差分串行，×1/×4/×16 并行多 lane。分层：物理层（串扰、训练、8b/10b 或 128b/130b）、数据链路（ACK/重传、DLLP）、事务层（TLP，下一课）。缺口不是再画教学总线，而是<strong>点对点交换机</strong>把根端口接到端点。</p><p>链路训练协商速率与宽度。热插拔与电源状态点名。本课不把 SerDes 模拟前端画成光刻。</p><h3 id="lane-不是「内存通道」" tabindex="-1">lane 不是「内存通道」 <a class="header-anchor" href="#lane-不是「内存通道」" aria-label="Permalink to &quot;lane 不是「内存通道」&quot;">​</a></h3><p>DRAM 通道有命令/地址/数据时序；PCIe lane 是包交换串行链路。把 ×16 当成另一条 DDR 通道，一致性与地址译码会错——设备用 BAR 映射，不是 JEDEC 行地址。HBM 更不是 PCIe。</p><p><span class="marginnote">PCI-SIG 基规范是权威。CA:AQA 与 COD 讨论 I/O 互连演进。本课用规范层次，不背每代 GT/s 表当作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>根复合体发出配置与内存 TLP。交换机基于地址/ID 路由。端点（SSD 控制器、NIC）实现 BAR。带宽粗算：每 lane 有效速率 × 宽度 × 方向（全双工）。开销：编码、DLLP、TLP 头，使有效载荷低于标称。</p><p><span class="marginnote">数字实例：PCIe 3.0 每 lane 标称 8 GT/s，经 128b/130b 编码后约 985 MB/s。你插一张 ×4 的 NVMe SSD，理论上限约 985 × 4 ≈ 3.9 GB/s——再快的盘插在 ×1 的槽上也只有约 1 GB/s，宽度直接封顶带宽。</span></p>',12)),(s(),E(i,null,{default:e(()=>[B(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RC%5B%22%E6%A0%B9%E5%A4%8D%E5%90%88%E4%BD%93%22%5D%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%20lane%22%5D%0A%20%20PHY%20--%3E%20DL%5B%22%E6%95%B0%E6%8D%AE%E9%93%BE%E8%B7%AF%20ACK%22%5D%0A%20%20DL%20--%3E%20TL%5B%22%E4%BA%8B%E5%8A%A1%E5%B1%82%20TLP%22%5D%0A%20%20TL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ATLP%20%E7%B1%BB%E5%9E%8B%E4%B8%8E%20BAR%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"NVMe SSD 是端点，内部再接 NAND 并行；PCIe 只负责到主机内存/CPU。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[l("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"下一课事务：Cfg/Mem/IO/Message，BAR 窗口把 MMIO 落到设备寄存器。MSI-X 用 TLP 写中断。本课先把「串行分层链路」钉住，替代教学共享总线的频率神话。",-1)),(s(),E(i,null,{default:e(()=>[B(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20OLD%5B%22%E6%97%A7%E4%B8%96%E7%95%8C%EF%BC%9A%E5%85%B1%E4%BA%AB%E5%B9%B6%E8%A1%8C%E6%80%BB%E7%BA%BF%22%5D%0A%20%20%20%20CPU1%5B%22CPU%22%5D%20---%20BUS%5B%22%E4%B8%80%E6%9D%A1%E5%85%B1%E4%BA%AB%E6%80%BB%E7%BA%BF%22%5D%0A%20%20%20%20BUS%20---%20D1%5B%22%E8%AE%BE%E5%A4%87%201%22%5D%0A%20%20%20%20BUS%20---%20D2%5B%22%E8%AE%BE%E5%A4%87%202%22%5D%0A%20%20%20%20BUS%20---%20D3%5B%22%E8%AE%BE%E5%A4%87%203%22%5D%0A%20%20end%0A%20%20subgraph%20NEW%5B%22%E6%96%B0%E4%B8%96%E7%95%8C%EF%BC%9APCIe%20%E7%82%B9%E5%AF%B9%E7%82%B9%22%5D%0A%20%20%20%20CPU2%5B%22%E6%A0%B9%E5%A4%8D%E5%90%88%E4%BD%93%22%5D%20---%7C%E4%B8%93%E7%94%A8%20lane%7C%20SW%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%22%5D%0A%20%20%20%20SW%20---%7Clane%20%C3%97N%7C%20E1%5B%22SSD%22%5D%0A%20%20%20%20SW%20---%7Clane%20%C3%971%7C%20E2%5B%22%E7%BD%91%E5%8D%A1%22%5D%0A%20%20%20%20SW%20---%7Clane%20%C3%9716%7C%20E3%5B%22GPU%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>这张图回答的问题是：为什么需要一个「交换机」？共享总线上所有设备抢同一组线，必须先仲裁；PCIe 里每个端点独享一条到交换机的链路，可以同时各自收发。交换机按地址决定每个包往哪个下游端口转发——这就是「点对点」三个字的实际含义。</p><p><span class="marginnote">直觉类比：lane 就像一条双向两车道的专用匝道——发送一对差分线走一个方向、接收一对走另一方向，永远不用等对面来车；链路宽度 ×N 就是并排修 N 条这样的匝道。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 CXL 全缓存一致协议（点名为 PCIe 物理上的近亲即可）。不把以太网 MAC 当 PCIe。不写光模块。不进入大模型多卡拓扑品牌。</p><p><span class="marginnote">常见误区：以为「×16 的槽插 ×4 的盘会烧坏」或「插上就一定跑满 ×16」。实际上链路宽度是开机时训练协商出来的：双方按各自支持的最大宽度取交集，×4 设备在 ×16 槽里就跑 ×4，互不伤害，只是带宽没吃满。</span></p><p>后课默认：PCIe 是分层点对点串行互连；宽度用 lane 数表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享并行 PCI 被点对点 PCIe 替代。</li><li>物理 / 数据链路 / 事务三层；lane 可聚合。</li><li>下一课才是 TLP 与 BAR 地址窗口。</li><li>出处：PCI-SIG PCIe Base Spec；Hennessy and Patterson, CA:AQA；Patterson and Hennessy, COD。</li></ul>',8))])}const u=o(C,[["render",d]]);export{S as __pageData,u as default};
